head.script:
try {
  var sidhGet = function (k) { try { return localStorage.getItem(k); } catch (e) { return null; } };
  var sidhRoot = document.documentElement;
  if (sidhGet('sidh-dark') === '1') { sidhRoot.classList.add('dark'); }
  if (sidhGet('sidh-hc') === '1') { sidhRoot.classList.add('hc'); }
  var sidhFs = sidhGet('sidh-fs');
  if (sidhFs) { sidhRoot.style.fontSize = sidhFs + '%'; }
} catch (e) {}

head.b:skin:
/* ============================================================
   SIDH-Style Blogger Theme (GIGW-inspired, Citizen-Centric UI)
   Design inspired by Skill India Digital Hub layout language
   ============================================================ */

/* Variable definitions
====================
<Variable name="keycolor" description="Primary Color (Blue)" type="color" default="#14418f" value="#14418f"/>
<Variable name="accent.color" description="Accent Color (Saffron)" type="color" default="#e8630a" value="#e8630a"/>
<Variable name="body.text.color" description="Body Text Color" type="color" default="#1c2433" value="#1c2433"/>
<Variable name="body.bg.color" description="Page Background Color" type="color" default="#f3f5f9" value="#f3f5f9"/>
*/

:root{
  --brand:$(keycolor);
  --brand-dark:#0c2d66;
  --brand-dark:color-mix(in srgb, $(keycolor) 76%, #000);
  --saffron:$(accent.color);
  --saffron-dark:#b9510a;
  --saffron-dark:color-mix(in srgb, $(accent.color) 80%, #000);
  --green:#138808;
  --text:$(body.text.color);
  --bg:$(body.bg.color);
  --card:#ffffff;
  --muted:#5b6577;
  --line:#e0e6f2;
  --soft:#f0f4fc;
  --soft:color-mix(in srgb, $(keycolor) 6%, #ffffff);
  --radius:12px;
  --shadow:0 1px 2px rgba(12,35,80,.07), 0 6px 18px rgba(12,35,80,.07);
  --shadow-lg:0 10px 30px rgba(12,35,80,.14);
}

/* ---------- Base / Reset ---------- */
*,*::before,*::after{box-sizing:border-box}
html{font-size:100%;scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{
  margin:0;
  font-family:'Noto Sans','Noto Sans Devanagari','Segoe UI',Roboto,Arial,'Helvetica Neue',sans-serif;
  font-size:1rem;
  line-height:1.7;
  color:var(--text);
  background:var(--bg);
}
img{max-width:100%;height:auto}
a{color:var(--brand)}
a:hover{color:var(--saffron-dark)}
h1,h2,h3,h4,h5,h6{line-height:1.35;color:var(--text)}
button{font-family:inherit}
::selection{background:var(--saffron);color:#fff}

:focus{outline:none}
:focus-visible{outline:3px solid var(--saffron);outline-offset:2px;border-radius:4px}

.container{max-width:1200px;margin:0 auto;padding:0 16px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* Skip link */
.skip-link{
  position:absolute;left:-9999px;top:0;z-index:2000;
  background:var(--saffron);color:#fff;font-weight:700;
  padding:10px 18px;border-radius:0 0 10px 0;text-decoration:none;
}
.skip-link:focus{left:0;top:0;color:#fff}

/* ---------- Reading progress (item pages) ---------- */
#read-progress{
  position:fixed;top:0;left:0;height:3px;width:0;z-index:1200;
  background:linear-gradient(90deg,var(--saffron),var(--green));
  display:none;
}
body.item #read-progress{display:block}

/* ---------- Back to top ---------- */
#to-top{
  position:fixed;right:20px;bottom:22px;z-index:900;
  width:46px;height:46px;border-radius:50%;border:0;cursor:pointer;
  background:var(--saffron);color:#fff;font-size:1.15rem;line-height:1;
  box-shadow:var(--shadow-lg);
  opacity:0;visibility:hidden;transform:translateY(10px);
  transition:opacity .25s ease,transform .25s ease,visibility .25s;
}
#to-top.show{opacity:1;visibility:visible;transform:translateY(0)}
#to-top:hover{background:var(--saffron-dark)}

/* ---------- Tricolor strip + Accessibility bar ---------- */
.tricolor{
  height:4px;
  background:linear-gradient(90deg,#ff9933 0 33.3%,#eef2f8 33.3% 66.6%,#138808 66.6% 100%);
}
.a11y-bar{background:var(--brand-dark);color:#d9e4ff;font-size:.85rem}
.a11y-inner{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:6px 16px;min-height:40px}
.a11y-left{display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.a11y-link{color:#fff;text-decoration:none;display:inline-flex;align-items:center;gap:6px}
.a11y-link:hover{color:#ffd9b0;text-decoration:underline}
.a11y-tools{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.a11y-label{opacity:.85;margin-right:2px}
.a11y-btn{
  background:rgba(255,255,255,.12);color:#fff;
  border:1px solid rgba(255,255,255,.32);border-radius:6px;
  padding:2px 9px;font-size:.82rem;line-height:1.5;cursor:pointer;min-width:32px;
}
.a11y-btn:hover{background:rgba(255,255,255,.25)}
.a11y-btn[aria-pressed="true"]{background:var(--saffron);border-color:var(--saffron);color:#fff}
.gt-wrap{margin-left:4px}
.goog-te-gadget{font-size:.8rem !important;font-family:inherit !important}
.goog-te-gadget-simple{
  background:rgba(255,255,255,.12) !important;
  border:1px solid rgba(255,255,255,.32) !important;border-radius:6px !important;
  padding:2px 6px !important;
}
.goog-te-gadget-simple .goog-te-gadget-icon{display:none}
.goog-te-gadget-simple a, .goog-te-menu-value{color:#fff !important;text-decoration:none}
.goog-te-banner-frame,.skiptranslate#goog-gt-tt{display:none !important}
body{top:0 !important}

/* ---------- Header ---------- */
.site-header{background:var(--card);border-bottom:1px solid var(--line)}
.header-grid{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:16px}
.header-brand{flex:1 1 260px;min-width:220px}
.Header .titlewrapper{margin:0}
.Header .title{margin:0;font-size:1.55rem;font-weight:800;letter-spacing:-.3px}
.Header .title a{color:var(--brand);text-decoration:none}
.Header .title a:hover{color:var(--saffron-dark)}
.Header .descriptionwrapper{margin:2px 0 0}
.Header .description{margin:0;font-size:.9rem;color:var(--muted)}
.Header img{max-height:72px;width:auto}
.header-search{display:flex;width:100%;max-width:430px;border:2px solid var(--line);border-radius:10px;overflow:hidden;background:var(--card)}
.header-search:focus-within{border-color:var(--brand)}
.header-search input[type="search"]{
  flex:1;min-width:0;border:0;padding:10px 14px;font-size:.95rem;background:transparent;color:var(--text);
}
.header-search input[type="search"]:focus{outline:none}
.header-search .search-btn{
  border:0;background:var(--brand);color:#fff;padding:0 16px;cursor:pointer;
  display:inline-flex;align-items:center;justify-content:center;
}
.header-search .search-btn:hover{background:var(--brand-dark)}

/* ---------- Navigation ---------- */
.main-nav{background:var(--brand);position:sticky;top:0;z-index:800;box-shadow:0 2px 8px rgba(10,25,60,.18)}
.nav-wrap{display:flex;align-items:stretch;flex-wrap:wrap}
.nav-toggle{
  display:none;background:transparent;border:0;color:#fff;font-weight:700;font-size:.95rem;
  padding:12px 14px;cursor:pointer;align-items:center;gap:8px;
}
.nav-toggle:hover{background:var(--brand-dark)}
.main-nav .widget h2, .main-nav .widget .title{display:none}
#LinkList1 .widget-content > ul{display:flex;flex-wrap:wrap;list-style:none;margin:0;padding:0}
#LinkList1 .widget-content > ul > li{margin:0}
#LinkList1 .widget-content > ul > li > a{
  display:block;color:#fff;text-decoration:none;font-weight:600;font-size:.95rem;
  padding:13px 16px;border-bottom:3px solid transparent;
}
#LinkList1 .widget-content > ul > li > a:hover{background:var(--brand-dark);color:#fff}
#LinkList1 .widget-content > ul > li > a.active{border-bottom-color:var(--saffron);color:#ffe1c2}

/* ---------- Hero ---------- */
.hero{margin:22px 0 6px}
.hero .widget{margin:0}
.hero .widget-content{
  background:linear-gradient(135deg,#eaf1ff 0%,#ffffff 52%,#fff3e6 100%);
  border:1px solid var(--line);border-radius:18px;padding:26px;
}
.hero-inner{display:grid;grid-template-columns:1.15fr .95fr;gap:26px;align-items:center}
.hero-kicker{
  display:inline-block;margin:0 0 10px;padding:3px 12px;border-radius:999px;
  background:color-mix(in srgb, var(--saffron) 12%, #ffffff);color:var(--saffron-dark);
  font-size:.82rem;font-weight:700;
}
.hero-title{margin:0 0 8px;font-size:clamp(1.35rem,2.6vw,1.9rem);font-weight:800;color:var(--brand-dark)}
.hero-sub{margin:0 0 16px;color:var(--muted);font-size:1rem;max-width:56ch}
.hero-actions{display:flex;gap:10px;flex-wrap:wrap}
.hero-cards{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.hero-card{
  display:block;background:var(--card);border:1px solid var(--line);border-radius:12px;
  padding:14px;text-decoration:none;transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;
}
.hero-card:hover{transform:translateY(-3px);box-shadow:var(--shadow);border-color:var(--saffron)}
.hc-ico{display:block;font-size:1.45rem;line-height:1;margin-bottom:6px}
.hero-card b{display:block;color:var(--brand-dark);font-size:.98rem}
.hero-card small{color:var(--muted);font-size:.8rem}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex;align-items:center;gap:8px;border-radius:9px;padding:10px 18px;
  font-weight:700;font-size:.93rem;text-decoration:none;cursor:pointer;border:2px solid transparent;
}
.btn-primary{background:var(--brand);color:#fff}
.btn-primary:hover{background:var(--brand-dark);color:#fff}
.btn-outline{background:transparent;color:var(--brand);border-color:var(--brand)}
.btn-outline:hover{background:var(--brand);color:#fff}
.btn-sm{padding:6px 12px;font-size:.85rem}

/* ---------- Breadcrumbs ---------- */
.breadcrumbs{font-size:.85rem;color:var(--muted);margin:18px 0 0;padding:0 2px}
.breadcrumbs a{color:var(--brand);text-decoration:none}
.breadcrumbs a:hover{text-decoration:underline}
.crumb-sep{margin:0 6px;color:var(--muted)}
.crumb-current{color:var(--muted)}

/* ---------- Main layout ---------- */
.main-wrap{
  display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:26px;
  align-items:start;margin:18px auto 30px;
}
body.static_page .main-wrap{grid-template-columns:minmax(0,1fr)}
body.static_page .sidebar-area{display:none}
body.error_page .main-wrap{grid-template-columns:minmax(0,1fr)}
body.error_page .sidebar-area{display:none}

/* ---------- Post cards (index / archive / search) ---------- */
body.index .blog-posts, body.archive .blog-posts{
  display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:20px;
}
body.index .blog-posts > *, body.archive .blog-posts > *{
  background:var(--card);border:1px solid var(--line);border-top:3px solid transparent;
  border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column;
  transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;
}
body.index .blog-posts > *:hover, body.archive .blog-posts > *:hover{
  transform:translateY(-3px);box-shadow:var(--shadow);border-top-color:var(--saffron);
}
.blog-posts .post{padding:16px 16px 18px;display:flex;flex-direction:column;flex:1}
.blog-posts .post-title{font-size:1.12rem;font-weight:700;margin:0 0 8px;line-height:1.45}
.blog-posts .post-title a{color:var(--brand-dark);text-decoration:none}
.blog-posts .post-title a:hover{color:var(--saffron-dark)}
body.index .blog-posts img, body.archive .blog-posts img{
  width:100%;height:168px;object-fit:cover;border-radius:9px;float:none;
}
body.index .blog-posts .snippet-thumbnail, body.archive .blog-posts .snippet-thumbnail,
body.index .blog-posts .item-thumbnail{
  float:none;margin:0 0 12px;display:block;
}
body.index .post-snippet, body.archive .post-snippet, body.index .snippet{
  color:var(--muted);font-size:.92rem;margin:0 0 12px;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;
}
body.index .byline, body.archive .byline, .post-header{
  color:var(--muted);font-size:.8rem;margin:0 0 10px;
}
body.index .blog-posts .post-share-buttons{display:none}
.blog-posts .jump-link{margin-top:auto;padding-top:6px}
.jump-link a{
  display:inline-flex;align-items:center;gap:7px;
  background:var(--saffron);color:#fff;text-decoration:none;font-weight:700;font-size:.88rem;
  padding:8px 15px;border-radius:8px;
}
.jump-link a::after{content:'\2192'}
.jump-link a:hover{background:var(--saffron-dark);color:#fff}
.post-labels{font-size:.78rem;margin-top:12px}
.post-labels a{
  display:inline-block;background:var(--soft);color:var(--brand);text-decoration:none;
  padding:2px 9px;border-radius:999px;margin:0 5px 5px 0;border:1px solid var(--line);
}
.post-labels a:hover{background:var(--brand);color:#fff;border-color:var(--brand)}

/* ---------- Single post / static page ---------- */
body.item .blog-posts, body.static_page .blog-posts{display:block}
.content-section .widget.Blog{margin:0}
.status-msg-wrap{
  display:block;background:#fff8ec;border:1px solid #f1d9a8;border-radius:10px;
  color:#7a5700;padding:12px 16px;font-size:.92rem;margin:0 0 18px;
}
.status-msg-wrap a{color:var(--brand)}
.post-outer-container, .post-outer{margin:0}
body.item .post-outer, body.static_page .post-outer, body.item .post-outer-container{
  background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
  box-shadow:var(--shadow);
}
body.item .post-outer, body.static_page .post-outer{border:0;box-shadow:none}
body.item .post, body.static_page .post{
  background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
  padding:26px 28px 28px;box-shadow:var(--shadow);
}
.post-title{color:var(--brand-dark)}
body.item .post-title, body.static_page .post-title{font-size:1.65rem;margin:0 0 10px;font-weight:800}
body.item .post-header, body.static_page .post-header{
  display:flex;flex-wrap:wrap;gap:6px 14px;color:var(--muted);font-size:.85rem;
  padding-bottom:14px;margin-bottom:6px;border-bottom:1px solid var(--line);
}
body.item .post-header a, body.static_page .post-header a{color:var(--muted);text-decoration:none}
body.item .post-header a:hover{color:var(--saffron-dark)}

/* Post body typography */
.post-body{font-size:1.02rem;line-height:1.8;margin-top:14px;word-wrap:break-word}
.post-body h2{font-size:1.35rem;margin:1.5em 0 .55em;padding-bottom:6px;border-bottom:2px solid var(--line);color:var(--brand-dark)}
.post-body h3{font-size:1.18rem;margin:1.4em 0 .5em;color:var(--brand-dark)}
.post-body h4{font-size:1.05rem;margin:1.3em 0 .45em}
.post-body p{margin:.85em 0}
.post-body ul,.post-body ol{margin:.85em 0;padding-left:1.5em}
.post-body li{margin:.32em 0}
.post-body a{text-decoration:underline;text-underline-offset:3px}
.post-body blockquote{
  margin:1.2em 0;padding:14px 18px;border-left:4px solid var(--brand);
  background:var(--soft);border-radius:0 10px 10px 0;color:var(--muted);
}
.post-body blockquote p{margin:.35em 0}
.post-body img{border-radius:10px}
.post-body iframe{max-width:100%;border:0;border-radius:10px}
.post-body hr{border:0;border-top:1px dashed var(--line);margin:1.7em 0}
.post-body code{
  background:var(--soft);color:var(--brand-dark);padding:2px 6px;border-radius:6px;
  font-size:.88em;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
.post-body pre{
  position:relative;background:#0e1c36;color:#d9e6ff;padding:40px 18px 16px;border-radius:12px;
  overflow:auto;font-size:.86rem;line-height:1.6;
  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
.post-body pre code{background:transparent;color:inherit;padding:0}
.copy-btn{
  position:absolute;top:8px;right:8px;background:#22386a;color:#cfe0ff;
  border:1px solid #3a568f;border-radius:7px;padding:4px 10px;font-size:.75rem;cursor:pointer;
}
.copy-btn:hover{background:var(--saffron);border-color:var(--saffron);color:#fff}
.table-scroll{overflow-x:auto;margin:1.1em 0;border-radius:10px;border:1px solid var(--line)}
.post-body table{width:100%;border-collapse:collapse;font-size:.93rem;margin:0}
.post-body th{background:var(--soft);color:var(--brand-dark);text-align:left}
.post-body th,.post-body td{padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:top}
.post-body tr:nth-child(even) td{background:color-mix(in srgb, var(--brand) 3%, var(--card))}
.ext-link::after{content:' \2197';font-size:.85em}

/* Reading time + TOC */
.reading-time{
  display:inline-block;background:var(--soft);color:var(--brand-dark);
  border:1px solid var(--line);border-radius:999px;padding:4px 14px;
  font-size:.82rem;margin:14px 0 0;
}
.post-toc{
  background:var(--soft);border:1px solid var(--line);border-radius:12px;
  padding:14px 18px;margin:18px 0 22px;
}
.post-toc summary{cursor:pointer;font-weight:800;color:var(--brand-dark);font-size:.98rem}
.post-toc ol{margin:10px 0 2px;padding-left:22px}
.post-toc li{margin:5px 0;font-size:.93rem}
.post-toc a{color:var(--brand);text-decoration:none}
.post-toc a:hover{color:var(--saffron-dark);text-decoration:underline}

/* Post footer (item) */
body.item .post-footer, body.static_page .post-footer{
  margin-top:22px;padding-top:16px;border-top:1px solid var(--line);
}
body.item .post-labels{margin:0 0 10px}

/* ---------- Pager ---------- */
#blog-pager{display:flex;justify-content:center;align-items:center;gap:14px;margin:26px 0 8px;padding:0}
#blog-pager a{
  display:inline-block;background:var(--card);border:2px solid var(--brand);color:var(--brand);
  font-weight:700;font-size:.9rem;text-decoration:none;padding:9px 20px;border-radius:9px;
}
#blog-pager a:hover{background:var(--brand);color:#fff}
.blog-mobile-link{display:none}

/* ---------- Comments ---------- */
.comments{
  background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
  padding:20px 22px;margin:24px 0 0;
}
.comments h3,.comments h4{margin:0 0 14px;font-size:1.1rem;color:var(--brand-dark)}
.comments .comments-content{font-size:.95rem}
.comment-thread ol{list-style:none;margin:0;padding:0}
.comment-thread ol ol{padding-left:0}
.comment{border:1px solid var(--line);border-radius:12px;padding:12px 15px;margin:0 0 14px;background:var(--card)}
.comment-replies{margin-left:34px;border-left:3px solid var(--line);padding-left:14px}
.comment-header{font-size:.83rem;color:var(--muted)}
.comment-header .user{font-style:normal;font-weight:700;color:var(--text)}
.comment-header .datetime a{color:var(--muted);text-decoration:none}
.avatar-image-container img{border-radius:50%;width:38px;height:38px}
.comment-content{margin:6px 0;font-size:.95rem}
.comment-actions a,.comment .comment-reply{
  display:inline-block;font-size:.8rem;font-weight:700;text-decoration:none;
  color:var(--brand);border:1px solid var(--line);border-radius:7px;padding:3px 10px;margin:4px 6px 0 0;
}
.comment-actions a:hover{background:var(--brand);color:#fff;border-color:var(--brand)}
.deleted-comment{color:var(--muted);font-style:italic}
#comment-editor,#comment-holder,.comment-form iframe{width:100%;max-width:100%}
.comment-form h4{margin:0 0 8px}
.loadmore a{color:var(--brand);font-weight:700;text-decoration:none}

/* ---------- Sidebar ---------- */
.sidebar .widget{
  background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
  margin-bottom:20px;overflow:hidden;
}
.sidebar .widget h2,.sidebar .widget h3{
  position:relative;margin:0;padding:13px 16px;font-size:1rem;font-weight:800;color:var(--brand-dark);
  background:linear-gradient(90deg,var(--soft),transparent 70%);border-bottom:1px solid var(--line);
}
.sidebar .widget h2::after,.sidebar .widget h3::after{
  content:'';position:absolute;left:0;bottom:-1px;width:54px;height:3px;background:var(--saffron);
}
.sidebar .widget-content{padding:16px}
.popular-posts ul{list-style:none;margin:0;padding:0}
.popular-posts li{display:flow-root;padding:12px 0;border-bottom:1px dashed var(--line)}
.popular-posts li:last-child{border-bottom:0;padding-bottom:0}
.popular-posts .item-thumbnail{float:left;margin:3px 12px 4px 0}
.popular-posts .item-thumbnail img{width:74px;height:58px;object-fit:cover;border-radius:8px;display:block}
.popular-posts .item-title{font-size:.94rem;font-weight:700;line-height:1.4}
.popular-posts .item-title a{color:var(--brand-dark);text-decoration:none}
.popular-posts .item-title a:hover{color:var(--saffron-dark)}
.popular-posts .item-snippet{font-size:.82rem;color:var(--muted);margin-top:2px;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.cloud-label-widget-content{display:flex;flex-wrap:wrap;gap:8px}
.cloud-label-widget-content .label-size{margin:0}
.cloud-label-widget-content .label-size a{
  display:inline-block;background:var(--soft);color:var(--brand);text-decoration:none;
  border:1px solid var(--line);border-radius:999px;padding:4px 12px;font-size:.85rem;
}
.cloud-label-widget-content .label-size a:hover{background:var(--brand);color:#fff;border-color:var(--brand)}
.cloud-label-widget-content .label-count{color:var(--muted);font-size:.78rem}
.list-label-widget-content ul,.cloud-label-widget-content{margin:0;padding:0;list-style:none}
.list-label-widget-content li{padding:8px 0;border-bottom:1px dashed var(--line)}
.list-label-widget-content li:last-child{border-bottom:0}
.list-label-widget-content a{color:var(--brand-dark);text-decoration:none;font-size:.92rem}
.list-label-widget-content .label-count{
  float:right;background:var(--soft);color:var(--brand);border-radius:999px;
  padding:1px 9px;font-size:.78rem;border:1px solid var(--line);
}
#ArchiveList ul{list-style:none;margin:0;padding:0}
#ArchiveList .flat li{padding:7px 0;border-bottom:1px dashed var(--line)}
#ArchiveList .flat li:last-child{border-bottom:0}
#ArchiveList a{color:var(--brand-dark);text-decoration:none;font-size:.92rem}
#ArchiveList a:hover{color:var(--saffron-dark)}
#ArchiveList .post-count{float:right;color:var(--muted);font-size:.8rem}
.sidebar .widget .follow-btns{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}

/* ---------- Footer ---------- */
.site-footer{background:#0d2350;color:#c9d6f2;margin-top:34px}
.footer-grid{
  display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:30px;
  padding:38px 16px 30px;max-width:1200px;margin:0 auto;
}
.site-footer .widget{background:none;border:0;margin:0 0 6px}
.site-footer .widget h2,.site-footer .widget h3{
  color:#ffb26b;font-size:1rem;margin:0 0 12px;letter-spacing:.3px;
}
.site-footer .widget-content{font-size:.92rem;line-height:1.75}
.site-footer a{color:#c9d6f2}
.site-footer a:hover{color:#ffffff;text-decoration:underline}
.footer-badge{margin:12px 0 0;font-size:.85rem;color:#9fb6e2}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer ul li{padding:5px 0;border-bottom:1px dashed rgba(255,255,255,.14)}
.site-footer ul li:last-child{border-bottom:0}
.contact-list li{border-bottom:0 !important;padding:3px 0 !important}
.disclaimer{margin:10px 0 0;font-size:.82rem;color:#9fb6e2}
.footer-bottom{background:#081a3d}
.footer-bottom-inner{
  max-width:1200px;margin:0 auto;padding:14px 16px;display:flex;justify-content:space-between;
  align-items:center;gap:10px;flex-wrap:wrap;font-size:.84rem;color:#9fb6e2;
}
.footer-bottom .widget{margin:0;font-size:.84rem}
.footer-bottom .widget ul{list-style:none;margin:0;padding:0;display:flex;gap:14px;flex-wrap:wrap}
.footer-bottom a{color:#c9d6f2}
.footer-note{margin:0}

/* ---------- Dark mode ---------- */
html.dark{
  --bg:#0a1322;--card:#101d33;--text:#e7edfb;--muted:#9dabc7;--line:#24365c;
  --soft:#16264a;--shadow:0 1px 3px rgba(0,0,0,.5);
}
html.dark .site-header,html.dark .main-nav{background:var(--card)}
html.dark .main-nav{background:#101d33;border-bottom:1px solid var(--line)}
html.dark .Header .title a,html.dark .post-title,html.dark .hero-title,html.dark .post-body h2,
html.dark .post-body h3,html.dark .sidebar .widget h2,html.dark .sidebar .widget h3,
html.dark .comments h3,html.dark .comments h4,html.dark .hero-card b,html.dark .reading-time{
  color:#9cc0ff;
}
html.dark .post-body code,html.dark .post-labels a,html.dark .cloud-label-widget-content .label-size a,
html.dark .hero-kicker{background:#16264a;color:#9cc0ff;border-color:#24365c}
html.dark .hero .widget-content{background:linear-gradient(135deg,#122441 0%,#101d33 55%,#1a2340 100%);border-color:#24365c}
html.dark .hero-card{background:#101d33;border-color:#24365c}
html.dark .post-body th{background:#16264a;color:#9cc0ff}
html.dark .post-body tr:nth-child(even) td{background:#0d1830}
html.dark .post-body blockquote{background:#16264a;color:#b9c6e2}
html.dark .post-toc{background:#16264a}
html.dark .status-msg-wrap{background:#241d07;border-color:#5c4a12;color:#e8c96a}
html.dark .site-footer{background:#071433}
html.dark .footer-bottom{background:#040e24}
html.dark img{opacity:.92}
html.dark .header-search{background:var(--card)}
html.dark .tricolor{background:linear-gradient(90deg,#ff9933 0 33.3%,#1c2a45 33.3% 66.6%,#138808 66.6% 100%)}

/* ---------- High contrast mode ---------- */
html.hc{--bg:#000;--card:#000;--text:#ffff00;--muted:#ffff00;--line:#ffff00;--soft:#000;--shadow:none}
html.hc a{color:#ffff00 !important;text-decoration:underline !important}
html.hc .a11y-bar,html.hc .main-nav,html.hc .site-header{background:#000 !important;border-color:#ffff00}
html.hc .main-nav{border-bottom:3px solid #ffff00}
html.hc #LinkList1 .widget-content > ul > li > a{color:#ffff00 !important}
html.hc .a11y-btn{background:#000;color:#ffff00;border-color:#ffff00}
html.hc .a11y-btn[aria-pressed="true"]{background:#ffff00;color:#000}
html.hc .header-search{background:#000;border-color:#ffff00}
html.hc .header-search input{color:#ffff00}
html.hc .header-search .search-btn{background:#ffff00;color:#000}
html.hc .btn-primary,html.hc .jump-link a{background:#ffff00 !important;color:#000 !important}
html.hc .hero .widget-content{background:#000;border-color:#ffff00}
html.hc .post,html.hc .post-outer,html.hc .sidebar .widget,html.hc .comments{background:#000;border-color:#ffff00}
html.hc img{filter:grayscale(100%) contrast(1.1)}
html.hc #to-top{background:#ffff00;color:#000}
html.hc .site-footer,html.hc .footer-bottom{background:#000;border-top:2px solid #ffff00}
html.hc .post-body pre{background:#000;border:1px solid #ffff00}
html.hc .tricolor{background:#ffff00}

/* ---------- Responsive ---------- */
@media (max-width:1024px){
  .main-wrap{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:920px){
  .hero-inner{grid-template-columns:1fr}
  .nav-toggle{display:inline-flex}
  #LinkList1{display:none;width:100%;flex-basis:100%}
  #LinkList1.open{display:block}
  #LinkList1 .widget-content > ul{flex-direction:column}
  #LinkList1 .widget-content > ul > li > a{border-bottom:1px solid rgba(255,255,255,.16);border-left:4px solid transparent}
  #LinkList1 .widget-content > ul > li > a.active{border-left-color:var(--saffron);border-bottom:1px solid rgba(255,255,255,.16)}
  .a11y-label{display:none}
}
@media (max-width:640px){
  .header-grid{flex-direction:column;align-items:stretch}
  .header-search{max-width:100%}
  .Header .title{font-size:1.35rem}
  .hero .widget-content{padding:20px}
  .hero-cards{grid-template-columns:1fr 1fr}
  body.item .post,body.static_page .post{padding:18px 16px}
  body.item .post-title,body.static_page .post-title{font-size:1.35rem}
  #to-top{right:14px;bottom:16px}
}
@media (max-width:420px){
  .hero-cards{grid-template-columns:1fr}
}

/* ---------- Reduced motion & print ---------- */
@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{animation:none !important;transition:none !important}
  html{scroll-behavior:auto}
}
@media print{
  .a11y-bar,.tricolor,.main-nav,.header-search,.sidebar-area,.site-footer,#to-top,#read-progress,
  .hero,.breadcrumbs,.jump-link,.post-share-buttons,.comments,.post-toc{display:none !important}
  .main-wrap{display:block}
  body{background:#fff;color:#000}
  .post{border:0 !important;box-shadow:none !important;padding:0 !important}
  a{color:#000;text-decoration:underline}
}

body.script:
//
/* ============================================================
   SIDH-Style Blogger Theme - UI Controls & Enhancements
   Vanilla JS, defensive, no external dependencies required.
   ============================================================ */
(function () {
  'use strict';

  var d = document, root = d.documentElement, body = d.body;
  var reduce = false;
  try { reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}

  function lsGet(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { window.localStorage.setItem(k, v); } catch (e) {} }
  function bind(id, fn) { var el = d.getElementById(id); if (el) { el.addEventListener('click', fn); } }

  /* ---------- 1. Text size controls (A- / A / A+) ---------- */
  try {
    var SIZES = [87.5, 93.75, 100, 106.25, 112.5, 118.75, 125];
    var fsIdx = 2;
    var savedFs = lsGet('sidh-fs');
    if (savedFs) {
      var fi = SIZES.indexOf(parseFloat(savedFs));
      if (fi > -1) { fsIdx = fi; }
    }
    var applyFs = function () {
      root.style.fontSize = SIZES[fsIdx] + '%';
      lsSet('sidh-fs', String(SIZES[fsIdx]));
    };
    applyFs();
    bind('fs-dec', function () { if (fsIdx > 0) { fsIdx--; applyFs(); } });
    bind('fs-inc', function () { if (fsIdx < SIZES.length - 1) { fsIdx++; applyFs(); } });
    bind('fs-reset', function () { fsIdx = 2; applyFs(); });
  } catch (e) {}

  /* ---------- 2. High contrast + Dark mode toggles ---------- */
  try {
    var bindToggle = function (id, cls, key) {
      var el = d.getElementById(id);
      if (!el) { return; }
      var sync = function () {
        el.setAttribute('aria-pressed', root.classList.contains(cls) ? 'true' : 'false');
      };
      sync();
      el.addEventListener('click', function () {
        root.classList.toggle(cls);
        lsSet(key, root.classList.contains(cls) ? '1' : '0');
        sync();
      });
    };
    bindToggle('t-contrast', 'hc', 'sidh-hc');
    bindToggle('t-dark', 'dark', 'sidh-dark');
  } catch (e) {}

  /* ---------- 3. Mobile nav toggle + active link ---------- */
  try {
    var tog = d.getElementById('nav-toggle'), navList = d.getElementById('LinkList1');
    if (tog && navList) {
      tog.addEventListener('click', function () {
        var open = navList.classList.toggle('open');
        tog.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
      var here = location.pathname.replace(/\/+$/, '') || '/';
      var navLinks = navList.querySelectorAll('a');
      for (var nl = 0; nl < navLinks.length; nl++) {
        try {
          var u = new URL(navLinks[nl].getAttribute('href') || '', location.href);
          if (u.host === location.host && (u.pathname.replace(/\/+$/, '') || '/') === here) {
            navLinks[nl].classList.add('active');
            navLinks[nl].setAttribute('aria-current', 'page');
          }
        } catch (e) {}
      }
    }
  } catch (e) {}

  /* ---------- 4. Back to top + reading progress ---------- */
  try {
    var topBtn = d.getElementById('to-top');
    var bar = d.getElementById('read-progress');
    var onScroll = function () {
      var y = window.pageYOffset || root.scrollTop || 0;
      if (topBtn) {
        if (y > 400) { topBtn.classList.add('show'); } else { topBtn.classList.remove('show'); }
      }
      if (bar) {
        var h = body.scrollHeight - window.innerHeight;
        var p = h > 0 ? Math.min(100, Math.max(0, (y / h) * 100)) : 0;
        bar.style.width = p + '%';
      }
    };
    if (window.addEventListener) { window.addEventListener('scroll', onScroll, { passive: true }); }
    onScroll();
    bind('to-top', function () {
      window.scrollTo({ top: 0, behavior: reduce ? 'auto' : 'smooth' });
    });
  } catch (e) {}

  /* ---------- 5. Reading time (post pages) ---------- */
  try {
    if (body.classList.contains('item')) {
      var pb = d.querySelector('.post-body');
      if (pb && !d.querySelector('.reading-time')) {
        var words = (pb.textContent || '').trim().split(/\s+/).length;
        var mins = Math.max(1, Math.round(words / 180));
        var rt = d.createElement('p');
        rt.className = 'reading-time';
        rt.textContent = '\u0916\u094B\u091C \u0938\u0947 \u092A\u0939\u0932\u0947 \u092A\u0922\u093C\u0947\u0902 \u2014 Approx. reading time: ' + mins + ' min';
        pb.parentNode.insertBefore(rt, pb);
      }
    }
  } catch (e) {}

  /* ---------- 6. Auto Table of Contents (post pages) ---------- */
  try {
    if (body.classList.contains('item')) {
      var pb2 = d.querySelector('.post-body');
      if (pb2) {
        var heads = pb2.querySelectorAll('h2, h3, h4');
        if (heads.length >= 3) {
          var det = d.createElement('details');
          det.className = 'post-toc';
          var sum = d.createElement('summary');
          sum.textContent = '\u0935\u093F\u0937\u092F-\u0938\u0942\u091A\u0940 / Table of Contents';
          det.appendChild(sum);
          var ol = d.createElement('ol');
          for (var h = 0; h < heads.length; h++) {
            if (!heads[h].id) { heads[h].id = 'sec-' + (h + 1); }
            var a = d.createElement('a');
            a.href = '#' + heads[h].id;
            a.textContent = heads[h].textContent;
            var li = d.createElement('li');
            li.appendChild(a);
            ol.appendChild(li);
          }
          det.appendChild(ol);
          pb2.insertBefore(det, heads[0]);
        }
      }
    }
  } catch (e) {}

  /* ---------- 7. Copy button on code blocks ---------- */
  try {
    var pres = d.querySelectorAll('.post-body pre');
    for (var p = 0; p < pres.length; p++) {
      (function (pre) {
        if (pre.querySelector('.copy-btn')) { return; }
        var btn = d.createElement('button');
        btn.type = 'button';
        btn.className = 'copy-btn';
        btn.textContent = '\u0915\u0949\u092A\u0940 / Copy';
        btn.addEventListener('click', function () {
          var txt = pre.innerText || pre.textContent || '';
          var ok = function () {
            btn.textContent = '\u2713 Copied';
            setTimeout(function () { btn.textContent = '\u0915\u0949\u092A\u0940 / Copy'; }, 2000);
          };
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(txt).then(ok, function () {});
          } else {
            var ta = d.createElement('textarea');
            ta.value = txt;
            d.body.appendChild(ta);
            ta.select();
            try { d.execCommand('copy'); ok(); } catch (e) {}
            d.body.removeChild(ta);
          }
        });
        pre.appendChild(btn);
      })(pres[p]);
    }
  } catch (e) {}

  /* ---------- 8. Images: lazy load + HD thumbnails (s72-c fix) ---------- */
  try {
    var imgs = d.querySelectorAll('.post-body img, .blog-posts img, .widget img, .PopularPosts img');
    for (var im = 0; im < imgs.length; im++) {
      (function (g) {
        g.setAttribute('loading', 'lazy');
        g.setAttribute('decoding', 'async');
        var src = g.getAttribute('src') || '';
        if (src.indexOf('s72-c') > -1) {
          g.setAttribute('src', src.replace('s72-c', 'w480-h270-c'));
        }
        g.addEventListener('error', function () { g.style.visibility = 'hidden'; }, { once: true });
      })(imgs[im]);
    }
  } catch (e) {}

  /* ---------- 9. External links: new tab + safe rel ---------- */
  try {
    var exts = d.querySelectorAll('.post-body a[href^="http"]');
    for (var ex = 0; ex < exts.length; ex++) {
      try {
        if (exts[ex].host !== location.host) {
          exts[ex].setAttribute('target', '_blank');
          exts[ex].setAttribute('rel', 'noopener nofollow');
          exts[ex].classList.add('ext-link');
        }
      } catch (e) {}
    }
  } catch (e) {}

  /* ---------- 10. Wrap wide tables for horizontal scroll ---------- */
  try {
    var tables = d.querySelectorAll('.post-body table');
    for (var t = 0; t < tables.length; t++) {
      var tn = tables[t].parentNode;
      if (!tn || tn.className !== 'table-scroll') {
        var wrap = d.createElement('div');
        wrap.className = 'table-scroll';
        tn.insertBefore(wrap, tables[t]);
        wrap.appendChild(tables[t]);
      }
    }
  } catch (e) {}

  /* ---------- 11. Footer year ---------- */
  try {
    var y = d.getElementById('fyear');
    if (y) { y.textContent = String(new Date().getFullYear()); }
  } catch (e) {}

  /* ---------- 12. Google Translate (multilingual UI) ---------- */
  try {
    window.googleTranslateElementInit = function () {
      try {
        if (!window.google || !window.google.translate || !window.google.translate.TranslateElement) { return; }
        var pg = (d.documentElement.getAttribute('lang') || 'en').split('-')[0];
        new window.google.translate.TranslateElement({
          pageLanguage: pg,
          autoDisplay: false,
          layout: window.google.translate.TranslateElement.InlineLayout.SIMPLE,
          includedLanguages: 'en,hi,as,bn,gu,kn,kok,mai,mr,ne,or,pa,sa,sd,ta,te,ur'
        }, 'google_translate_element');
      } catch (e) {}
    };
    if (!d.getElementById('google_translate_element')) {
      /* element missing - skip silently */
    } else {
      var gt = d.createElement('script');
      gt.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
      gt.async = true;
      gt.onerror = function () {};
      (d.head || body).appendChild(gt);
    }
  } catch (e) {}

})();
//
